// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    Rejecter rejecter;

    function setUp() public {
        c = new MyContract();
        rejecter = new Rejecter();
        vm.deal(address(c), type(uint128).max);
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= type(uint128).max);
        uint256 balBefore = address(c).balance;
        vm.prank(address(this));
        bool ok;
        try c.sendTo(address(rejecter), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(
            !ok || (ok && address(c).balance == balBefore - amount && address(rejecter).balance == amount),
            "a sendTo that reports success must have actually delivered the funds"
        );
    }
}

contract Rejecter {
    fallback() external payable {
        revert("reject");
    }
}
